declare module '*.jsx' {
  const Component: React.FC<any>
  export default Component
}

declare module '*.tsx' {
  const Component: React.FC<any>
  export default Component
}

declare module '*.css' {
  const styles: any
  export default styles
}

declare module '*.png' {
  const src: string
  export default src
}

declare module '*.jpg' {
  const src: string
  export default src
}

declare module '*.jpeg' {
  const src: string
  export default src
}

declare module '*.gif' {
  const src: string
  export default src
}

declare module '*.svg' {
  const src: string
  export default src
}
